import SwiftUI

struct FlowsView:View{
 @EnvironmentObject var work:Workspace;@State private var recipe="[]";@State private var name="Review flow";@State private var op="check";@State private var path="$.id";@State private var value="\"value\"";@State private var type="string";@State private var pause=true;@State private var selectedRun="";@State private var correction="{}";@State private var selectedFailure="";@State private var flows:[[String:Any]]=[];@State private var outcomes:[[String:Any]]=[];@State private var showOutcomes=false;@State private var outcomeOffset=0;@State private var outcomeTotal=0;@State private var failureOffset=0;@State private var failureTotal=0
 var body:some View{VStack(alignment:.leading,spacing:12){HStack{Picker("Input revision",selection:$work.selectedRevision){ForEach(work.revisions,id:\.recordId){r in Text("\(r["name"] ?? "Dataset") · \(r["count"] ?? 0) records").tag(r.recordId)}};TextField("Flow name",text:$name);Button("Save flow version"){Task{do{let steps=try parse();if let r=await work.request("flow-save",["name":name,"steps":steps]){work.notice="Saved immutable flow \(r["id"] ?? "")";await loadFlows()}}catch{work.error=error.localizedDescription}}}};if !flows.isEmpty{Menu("Load saved flow"){ForEach(flows,id:\.recordId){flow in Button(flow["name"] as? String ?? flow.recordId){recipe=Workspace.pretty(flow["steps"] ?? []);name=flow["name"] as? String ?? "Flow"}}}}
 HSplitView{VStack(alignment:.leading,spacing:10){Text("Ordered stages").font(.headline);Text("Changes affect this draft. Running and staged flows retain their saved rules.").font(.caption).foregroundStyle(.secondary);HStack{Picker("Stage",selection:$op){Text("Validate field").tag("check");Text("Validate schema").tag("validate");Text("Set value").tag("set");Text("Remove field").tag("remove");Text("Keep matching").tag("include");Text("Exclude matching").tag("exclude");Text("Deduplicate").tag("dedupe")};TextField("JSON path",text:$path)};HStack{if op=="check"{Picker("Type",selection:$type){ForEach(["string","number","boolean","object","array"],id:\.self){Text($0)}}}else if ["set","include","exclude"].contains(op){TextField("JSON value, e.g. \"approved\" or 5",text:$value)};Button("Add stage"){addStage()}};TextEditor(text:$recipe).font(.system(.caption,design:.monospaced)).frame(minHeight:220);Toggle("Pause on validation failure",isOn:$pause);HStack{Button("Run saved draft",systemImage:"play.fill"){Task{do{if let r=await work.request("flow-start",["revision":work.selectedRevision,"steps":try parse(),"pauseOnFailure":pause]){selectedRun=r["id"] as? String ?? "";await work.datasets();work.notice="Flow started from an immutable input revision."}}catch{work.error=error.localizedDescription}}}.buttonStyle(.borderedProminent).disabled(work.selectedRevision.isEmpty);Spacer();Button("Clear draft"){recipe="[]"}}}.frame(minWidth:360)
 VStack(alignment:.leading,spacing:10){Text("Runs & validation").font(.headline);List(selection:$selectedRun){ForEach(work.runs,id:\.recordId){run in VStack(alignment:.leading,spacing:6){FieldView(field:Field("flow.state","State",run["state"] ?? "unknown",meaning:"Durable ETL execution state. Paused validation can be corrected and resumed."));HStack{FieldView(field:Field("flow.cursor","Checkpoint",run["cursor"] ?? 0,meaning:"Durably committed source position; accepted prefix is retained on resume."));FieldView(field:Field("flow.total","Input records",run["total"] ?? 0,meaning:"Total records in the immutable parent revision."))};Text(String(run.recordId.prefix(12))).font(.caption.monospaced())}.tag(run.recordId)}}.frame(minHeight:130,maxHeight:210);HStack{Button("Pause"){Task{_ = await work.request("flow-pause",["id":selectedRun]);await work.datasets()}};Button("Resume"){Task{_ = await work.request("flow-resume",["id":selectedRun]);await work.datasets()}};Button("Refresh failures"){Task{await loadFailures()}};Button("Review outcomes"){outcomeOffset=0;Task{await loadOutcomes();showOutcomes=true}}}.disabled(selectedRun.isEmpty);List(selection:$selectedFailure){ForEach(work.failures,id:\.recordId){f in VStack(alignment:.leading){Text(f["reason"] as? String ?? "Validation failure").foregroundStyle(.orange);Text(f["recordId"] as? String ?? "").font(.caption.monospaced()).lineLimit(1)}.tag(f.recordId)}}.frame(minHeight:80,maxHeight:150);HStack{Button("Previous failures"){failureOffset=max(0,failureOffset-25);Task{await loadFailures()}}.disabled(failureOffset==0);FieldView(field:Field("failure.total","Validation failures",failureTotal,meaning:"Total retained validation failures; the list is paginated."));Button("Next failures"){failureOffset+=25;Task{await loadFailures()}}.disabled(failureOffset+25>=failureTotal)};Text("Correct paused record").font(.caption);TextEditor(text:$correction).font(.system(.caption,design:.monospaced)).frame(minHeight:100);Button("Save correction"){Task{guard let f=work.failures.first(where:{$0.recordId==selectedFailure})else{return};do{let body=try JSONSerialization.jsonObject(with:Data(correction.utf8),options:.fragmentsAllowed);_ = await work.request("correct",["id":selectedRun,"record":f["recordId"] ?? "","body":body]);await loadFailures()}catch{work.error=error.localizedDescription}}}.disabled(selectedFailure.isEmpty);Text("Excluded, duplicate and quarantined records remain attributable in run outcomes. Source data is never deleted.").font(.caption).foregroundStyle(.secondary)}.frame(minWidth:340)}
 }.sheet(isPresented:$showOutcomes){VStack(alignment:.leading){HStack{Text("Run outcomes").font(.title2);Spacer();Button("Close"){showOutcomes=false}};HStack{Button("Previous"){outcomeOffset=max(0,outcomeOffset-25);Task{await loadOutcomes()}}.disabled(outcomeOffset==0);FieldView(field:Field("outcomes.total","Recorded outcomes",outcomeTotal,meaning:"Total retained record dispositions in this run."));Button("Next"){outcomeOffset+=25;Task{await loadOutcomes()}}.disabled(outcomeOffset+25>=outcomeTotal)};JsonPane(title:"Dispositions",value:outcomes,source:"ETL run outcomes")}.padding(20).frame(width:850,height:650)}.task{await work.datasets();await loadFlows()}.onChange(of:selectedRun){_,_ in failureOffset=0;Task{await loadFailures()}}.onChange(of:selectedFailure){_,_ in if let f=work.failures.first(where:{$0.recordId==selectedFailure}){correction=Workspace.pretty(f["body"] ?? [:])}}
 }
 func parse()throws->[[String:Any]]{let v=try JSONSerialization.jsonObject(with:Data(recipe.utf8));guard let steps=v as? [[String:Any]]else{throw NSError(domain:"Flow",code:1,userInfo:[NSLocalizedDescriptionKey:"A flow is a JSON array of stage objects."])};return steps}
 func addStage(){do{var steps=try parse();var step:[String:Any]=["op":op];switch op{case "check":step["path"]=path;step["type"]=type;step["required"]=true;step["onFailure"]="quarantine";case "validate":step["schema"]=["type":"object","properties":[:],"required":[],"additionalProperties":false];step["onFailure"]="quarantine";case "dedupe":break;case "remove":step["path"]=path;default:step["path"]=path;step[op=="set" ? "value":"equals"]=try JSONSerialization.jsonObject(with:Data(value.utf8),options:.fragmentsAllowed)};steps.append(step);recipe=Workspace.pretty(steps)}catch{work.error=error.localizedDescription}}
 func loadFailures()async{guard !selectedRun.isEmpty else{work.failures=[];return};let id=selectedRun;if let r=await work.request("failures",["id":id,"offset":failureOffset,"limit":25]),selectedRun==id{work.failures=r["failures"] as? [[String:Any]] ?? [];failureTotal=r["total"] as? Int ?? 0}}
 func loadOutcomes()async{let id=selectedRun;guard !id.isEmpty else{return};if let r=await work.request("outcomes",["id":id,"offset":outcomeOffset,"limit":25]),selectedRun==id{outcomes=r["outcomes"] as? [[String:Any]] ?? [];outcomeTotal=r["total"] as? Int ?? 0}}
 func loadFlows()async{if let r=await work.request("flows"){flows=r["flows"] as? [[String:Any]] ?? []}}
}
